const picked = $('Match Config Row').first().json;
let items = [];
try {
  const xml = $json.data || '';
  const itemBlocks = xml.match(/<item[\s\S]*?<\/item>/g) || xml.match(/<entry[\s\S]*?<\/entry>/g) || [];
  const now = new Date();
  const cutoff = new Date(now.getTime() - 30*24*60*60*1000);
  for (const block of itemBlocks) {
    const titleM = block.match(/<title[^>]*>([\s\S]*?)<\/title>/);
    const dateM = block.match(/<pubDate>([\s\S]*?)<\/pubDate>/) || block.match(/<published>([\s\S]*?)<\/published>/) || block.match(/<updated>([\s\S]*?)<\/updated>/);
    const linkM = block.match(/<link[^>]*>([\s\S]*?)<\/link>/) || block.match(/<link[^>]*href="([^"]*)"/);
    if (!titleM || !dateM) continue;
    const d = new Date(dateM[1].trim());
    if (isNaN(d)) continue;
    if (d < cutoff) continue;
    let title = titleM[1].replace(/<!\[CDATA\[|\]\]>/g,'').trim();
    items.push({ title, date: d, link: linkM ? linkM[1].trim() : '' });
  }
  items.sort((a,b) => b.date - a.date);
} catch (e) {}

let postDescription;
if (items.length > 0) {
  const top = items[0];
  postDescription = `Write about this recent development in ${picked.subject}: "${top.title}" (source: ${picked.publication}, published ${top.date.toDateString()}). Paraphrase in your own words -- never quote directly. Ground the post in this real, current story; add your own practical take as a data engineer / Fabric architect.`;
} else {
  postDescription = `Write a grounded, practical LinkedIn post about ${picked.subject}, drawing on current real developments in this space (from ${picked.publication}). No fetched article was available within the last 30 days, so speak from general current knowledge of the field -- stay factual, no invented specifics.`;
}

return [{ json: {
  'Post Description': postDescription,
  'Instructions': 'Keep it grounded and practical, not hype. Speak from my own experience as a data engineer/Fabric architect.',
  'Status': 'Pending',
  'Label': picked.label
}}];

const rows = $('Read Day Schedule').all().map(i => i.json);
const now = new Date();
const dayName = new Intl.DateTimeFormat('en-US', { weekday: 'long', timeZone: 'Australia/Brisbane' }).format(now);
const dateStr = new Intl.DateTimeFormat('en-CA', { timeZone: 'Australia/Brisbane' }).format(now);
const match = rows.find(r => r.Day === dayName);
const subject = match ? match.Subject : rows[0].Subject;
return [{ json: { day: dayName, subject: subject, dateStr: dateStr } }];

const today = $('Get Today Subject').first().json;
const configRows = $('Read Config').all().map(i => i.json);
const row = configRows.find(r => r.Subject === today.subject) || configRows[0];
const isGitHub = today.subject === 'GitHub';
const isRss = !isGitHub && row['Feed URL'] && (row['Feed URL'].includes('/feed') || row['Feed URL'].includes('.xml') || row['Feed URL'].includes('/news/') || row['Feed URL'].includes('atom'));
return [{ json: {
  day: today.day,
  dateStr: today.dateStr,
  subject: row.Subject,
  publication: row.Publication,
  feedUrl: row['Feed URL'],
  hasFeed: !!isRss,
  isGitHub: isGitHub,
  label: row.Subject.replace(/[^a-zA-Z0-9]+/g,'') + '_' + today.dateStr
}}];

const picked = $('Match Config Row').first().json;
const data = $json;
let postDescription;
if (data.items && data.items.length > 0) {
  const repo = data.items[0];
  postDescription = `Write about this real, currently trending GitHub repository: "${repo.full_name}" -- ${repo.description || 'no description provided'}. It has ${repo.stargazers_count.toLocaleString()} stars, primary language ${repo.language || 'unspecified'}, repo URL: ${repo.html_url}. Paraphrase in your own words -- never quote directly. Explain what it does and why it might be practically useful for a data engineer / Fabric architect; add your own honest take on whether it's worth trying. Mention the repo name and link naturally in the post.`;
} else {
  postDescription = `Write a grounded LinkedIn post about a notable, actively-maintained open source GitHub project relevant to data engineering or AI tooling. No specific repo data was available today -- speak generally about what makes a repo worth watching, stay factual, no invented specifics.`;
}
return [{ json: {
  'Post Description': postDescription,
  'Instructions': 'Keep it grounded and practical, not hype. Speak from my own experience as a data engineer/Fabric architect.',
  'Status': 'Pending',
  'Label': picked.label
}}];
